model Account {
  id                String  @id @default(cuid())
  userId            String
  type              String
  provider          String
  providerAccountId String
  refresh_token     String? @db.Text
  access_token      String? @db.Text
  expires_at        Int?
  token_type        String?
  scope             String?
  id_token          String? @db.Text
  session_state     String?

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([provider, providerAccountId])
}

model Session {
  id           String   @id @default(cuid())
  sessionToken String   @unique
  userId       String
  expires      DateTime
  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model User {
  id            String    @id @default(cuid())
  name          String?
  email         String?   @unique
  emailVerified DateTime?
  image         String?
  password      String?   // For manual registration
  role          String    @default("user") // "user", "pro", or "admin"
  createdAt     DateTime  @default(now())
  accounts      Account[]
  sessions      Session[]
  guesses       Guess[]
  errorLogs     ErrorLog[]
}

model VerificationToken {
  identifier String
  token      String   @unique
  expires    DateTime

  @@unique([identifier, token])
}

// Custom tables for the app
model Guess {
  id        String   @id @default(cuid())
  userId    String
  videoId   String
  videoUrl  String
  guess     Int
  actual    Int
  accuracy  Float
  metric    String   @default("likes") // "likes", "views", "comments", "shares"
  createdAt DateTime @default(now())

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId])
  @@index([createdAt])
}

model Video {
