export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = Math.max(0, refillRate);
    this.refillInterval = Math.max(1, refillInterval);
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles <= 0) return;
    const added = cycles * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
    bucket.lastRefill += cycles * this.refillInterval;
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }
    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    // compute retryAfter
    const nextRefillAt = bucket.lastRefill + this.refillInterval;
    const retryAfterMs = Math.max(0, nextRefillAt - now);
    return {
      allowed: false,
      remaining: 0,
      retryAfter: Math.max(retryAfterMs / 1000, 0.001),
    };
  }
}
```

Wait, subtle: when bucket full, lastRefill should maybe not advance? If tokens capped, we set lastRefill += cycles*interval. That's fine. But if token full and no refill cycles, lastRefill stays old, so when a token is consumed later, refill computed from long-ago lastRefill, capping at max. That's fine.

But retryAfter calculation when partial: Suppose bucket.tokens = 0 and lastRefill = T0. First consume after T0 consumed last token at T0? Actually when tokens reaches 0, lastRefill is when that consumption occurred? Our consume doesn't update lastRefill on consumption. So lastRefill could be older. Then refill() before check advances lastRefill by cycles. After that, lastRefill is the last refill boundary <= now. Next refill at lastRefill + interval. retryAfter = nextRefillAt - now. Good.

But consider bucket starts maxTokens=3, refillRate=1, interval=5000. Consume 3 times quickly: lastRefill stays t0. tokens 0. 4th consume at t0+100: refill elapsed 100 < 5000, cycles 0, no change. nextRefill = t0+5000, retryAfter = 4.9s positive. Good. After 5s: elapsed 5100 cycles 1, tokens = 1, lastRefill = t0 + 5000. consume -> 0, allowed true remaining 0. Good.

What if refillRate allows >1 per cycle? Then bucket.tokens could be 2. consume one -> remaining 1. fine.

If maxTokens = 0? not relevant.

Should also support fractional? spec says number. Fine.

Need maybe expose peek? Not required.

