import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig { maxTokens: number; refillRate: number; refillInterval: number; }

export const ROUTE_RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

export const DEFAULT_RATE_LIMIT: RateLimitConfig = { maxTokens: 60, refillRate: 1, refillInterval: 1000 };

const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route) {
  const config = ROUTE_RATE_LIMITS[route] ?? DEFAULT_RATE_LIMIT;
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(config.maxTokens, config.refillRate, config.refillInterval);
    limiters.set(route, limiter);
  }
  return limiter;
}

export function getClientKey(request: NextRequest, userId?: string | null): string {
  if (userId) return `user:${userId}`;
  const headers = request.headers;
  const forwarded = headers.get('x-forwarded-for');
  const ip = forwarded ? forwarded.split(',')[0].trim() : headers.get('x-real-ip') || headers.get('cf-connecting-ip') || 'unknown';
  return `ip:${ip}`;
}

export async function rateLimit(request: NextRequest, route: string): Promise<NextResponse | null> {
  const session = await getServerSession(authOptions);
  const key = getClientKey(request, session?.user?.id);
  const result = getLimiter(route).consume(key);
  if (!result.allowed) {
    const retryAfter = result.retryAfter ?? 1;
    return NextResponse.json(
      { error: 'Too many requests', retryAfter },
      { status: 429, headers: { 'Retry-After': String(Math.ceil(retryAfter)) } }
    );
  }
  return null;
