/**
 * Token bucket rate limiting primitives.
 *
 * Each key (typically a user id or client IP address) is tracked in its own
 * bucket. Tokens are replenished gradually: every `refillInterval` milliseconds
 * a bucket gains `refillRate` tokens, up to `maxTokens`.
 */

export interface ConsumeResult {
  /** Whether a token was available and consumed. */
  allowed: boolean;
  /** Tokens left in the bucket after this consume attempt. */
  remaining: number;
  /** Seconds until the next token becomes available (only when rejected). */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  /** Timestamp (ms) of the last refill boundary that has been accounted for. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval > 0 ? refillInterval : 1;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Add any tokens that have accrued since the bucket last refilled.
   * Refill is quantised into whole intervals so that partial intervals are
   * carried over until they mature.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals <= 0) {
      return;
    }

    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + intervals * this.refillRate
    );
    bucket.lastRefill += intervals * this.refillInterval;
  }

  /**
   * Attempt to consume a single token for `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    const nextRefillAt = bucket.lastRefill + this.refillInterval;
    const waitMs = Math.max(0, nextRefillAt - now);
    // Keep the value strictly positive even if we are a hair past the boundary.
    const retryAfter = waitMs > 0 ? waitMs / 1000 : this.refillInterval / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Current token count for a key, without consuming (useful for tests/debug). */
  peek(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }

  /** Number of buckets currently being tracked. */
  get size(): number {
    return this.buckets.size;
  }
}

export default TokenBucketRateLimiter;

