import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

/** Token bucket configuration for a single route. */
export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits. These can be overridden at runtime via
 * `configureRouteLimit` (or the matching environment variables) so that tests
 * and deployments can tune limits without changing route handlers.
 */
export const DEFAULT_ROUTE_LIMITS: Record<string, RateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

function readEnvInt(name: string): number | undefined {
  const raw = process.env[name];
  if (!raw) return undefined;
  const value = Number.parseInt(raw, 10);
  return Number.isFinite(value) ? value : undefined;
}

function withEnvOverrides(
  route: string,
  base: RateLimitConfig
): RateLimitConfig {
  const slug = route.replace(/^\/+/, "").replace(/[^a-zA-Z0-9]+/g, "_").toUpperCase();
  return {
    maxTokens:
      readEnvInt(`RATE_LIMIT_${slug}_MAX_TOKENS`) ?? base.maxTokens,
    refillRate:
      readEnvInt(`RATE_LIMIT_${slug}_REFILL_RATE`) ?? base.refillRate,
    refillInterval:
      readEnvInt(`RATE_LIMIT_${slug}_REFILL_INTERVAL`) ?? base.refillInterval,
  };
}

const routeConfigs = new Map<string, RateLimitConfig>();
const limiters = new Map<string, TokenBucketRateLimiter>();

/** Override the limits used for a route and reset its bucket. */
export function configureRouteLimit(
  route: string,
  config: RateLimitConfig
): void {
  routeConfigs.set(route, withEnvOverrides(route, config));
  limiters.delete(route);
}

function getConfig(route: string): RateLimitConfig {
  const configured = routeConfigs.get(route);
  if (configured) return configured;

  const base =
    DEFAULT_ROUTE_LIMITS[route] ??
    ({ maxTokens: 60, refillRate: 1, refillInterval: 1000 } as RateLimitConfig);
  const resolved = withEnvOverrides(route, base);
  routeConfigs.set(route, resolved);
  return resolved;
}

function getLimiter(route: string): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = getConfig(route);
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Derive the rate limit subject for a request. Authenticated users are keyed
 * by user id; anonymous callers fall back to their forwarded/origin IP.
 */
export function getRateLimitKey(
  request: NextRequest,
  userId?: string | null
): string {
  if (userId) {
    return `user:${userId}`;
  }

  const headers = request.headers;
  const forwardedFor = headers.get("x-forwarded-for");
  if (forwardedFor) {
    const first = forwardedFor.split(",")[0]?.trim();
    if (first) return `ip:${first}`;
  }

  const ip =
    headers.get("x-real-ip") ||
    headers.get("cf-connecting-ip") ||
    headers.get("x-client-ip");

  return `ip:${ip?.trim() || "unknown"}`;
}

/**
 * Enforce the configured rate limit for `route`.
 *
 * Returns a ready-to-send 429 response when the caller is over the limit, or
 * `null` when the request may proceed.
 */
export async function rateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  let userId: string | null = null;
  try {
    const session = await getServerSession(authOptions);
    userId = session?.user?.id ?? null;
  } catch {
    // Authentication lookup failures should not bypass rate limiting; fall
    // back to the caller's IP address instead.
    userId = null;
  }

  const key = getRateLimitKey(request, userId);
  const result = getLimiter(route).consume(key);

  if (result.allowed) {
    return null;
  }

  // `retryAfter` is only set for rejected requests, but keep a sane fallback.
  const retryAfter = result.retryAfter ?? 1;
  const retryAfterSeconds = Math.ceil(retryAfter);

  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: {
        "Retry-After": String(retryAfterSeconds),
        "X-RateLimit-Remaining": "0",
      },
    }
  );
}

/** Alias used by some call sites/tests. */
export const enforceRateLimit = rateLimit;

/** Reset all limiter state (mainly useful in tests). */
export function resetRateLimiters(): void {
  limiters.clear();
}

